import{_ as l,a0 as d,w as o,s as u,I as t,x as a,a1 as i,A as p,ao as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"在 Ubuntu 中使用 apt 命令列出可升级的软件包 | LCTT x X-CMD","titleTemplate":false,"description":"在 Ubuntu 中使用 apt 命令列出可升级的软件包 | LCTT (202207) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Ubuntu 中使用 apt 命令列出可升级的软件包 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Ubuntu 中使用 apt 命令列出可升级的软件包 | LCTT (202207) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202207/20220712 List Upgradable Packages With apt Command in Ubuntu","title":"在 Ubuntu 中使用 apt 命令列出可升级的软件包","tag":"202207","desc":""},"relativePath":"202207/20220712 List Upgradable Packages With apt Command in Ubuntu.md","filePath":"[post].md"}'),r={name:"202207/20220712 List Upgradable Packages With apt Command in Ubuntu.md"};function g(b,s,h,k,m,f){const e=d("Link");return o(),u("div",null,[s[36]||(s[36]=t("h1",{id:"在-ubuntu-中使用-apt-命令列出可升级的软件包",tabindex:"-1"},[a("在 Ubuntu 中使用 apt 命令列出可升级的软件包 "),t("a",{class:"header-anchor",href:"#在-ubuntu-中使用-apt-命令列出可升级的软件包","aria-label":"Permalink to “在 Ubuntu 中使用 apt 命令列出可升级的软件包”"},"​")],-1)),s[37]||(s[37]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/202207/24/230954qjko0c0sn55ohjf0.jpg",alt:""})],-1)),t("p",null,[i(e,{href:"https://itsfoss.com/apt-command-guide/"},{default:p(()=>[...s[0]||(s[0]=[a("apt 命令",-1)])]),_:1}),s[1]||(s[1]=a(" 用于 Debian 和 Ubuntu 中的包管理。虽然你可能已经熟悉安装和删除选项，但 ",-1)),s[2]||(s[2]=t("code",null,"apt",-1)),s[3]||(s[3]=a(" 还提供了一些额外的功能。",-1))]),s[38]||(s[38]=n(`<p>其中之一是能够查看系统上所有可升级的软件包。要显示它们，你所要做的就是在终端中使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt list --upgradable</span></span></code></pre></div><p>如你所见，你甚至不需要使用 <code>sudo</code> 来列出可更新的包。它只是列出了可以更新的包，而不会更新它们。</p><p>实际上，当你运行 <code>sudo apt update</code> 命令更新本地包仓库缓存时，<code>apt</code> 命令会添加此提示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Fetched 1,243 kB in 17s (71.4 kB/s)           </span></span>
<span class="line"><span>Reading package lists... Done</span></span>
<span class="line"><span>Building dependency tree... Done</span></span>
<span class="line"><span>Reading state information... Done</span></span>
<span class="line"><span>30 packages can be upgraded. Run &#39;apt list --upgradable&#39; to see them.</span></span></code></pre></div><p>我不记得在旧的 <code>apt-get</code> 命令中有任何类似的直接选项来列出所有可升级的包。这是 <code>apt</code> 在旧的 <code>apt-get</code> 命令之上添加的几个新功能之一。</p><p>让我们更详细地讨论一下。</p><h3 id="列出所有可升级的包" tabindex="-1">列出所有可升级的包 <a class="header-anchor" href="#列出所有可升级的包" aria-label="Permalink to “列出所有可升级的包”">​</a></h3>`,8)),t("p",null,[s[5]||(s[5]=a("你在这里应该知道的是",-1)),s[6]||(s[6]=t("strong",null,"你只能列出通过 APT 包管理器可用的更新",-1)),s[7]||(s[7]=a("。因此，如果你已将 PPA 或 ",-1)),i(e,{href:"https://itsfoss.com/adding-external-repositories-ubuntu/"},{default:p(()=>[...s[4]||(s[4]=[a("外部仓库",-1)])]),_:1}),s[8]||(s[8]=a(" 添加到系统的 ",-1)),s[9]||(s[9]=t("code",null,"sources.list",-1)),s[10]||(s[10]=a("，你也将看到来自它们的更新。",-1))]),s[39]||(s[39]=n(`<p>但是你不会在这里获得 AppImage、Flatpak、Snap 或一些其他打包格式的更新。</p><p>换句话说，它只适用于 APT 包。</p><p>因此，要列出 Ubuntu 或 Debian 系统上的所有可升级包，你应该首先更新本地包缓存：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update</span></span></code></pre></div><p>然后你的系统将知道可用的软件包更新。<code>apt</code> 命令告诉你在 update 命令结束时可以升级多少个软件包：</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/07/update-package-cache-ubuntu.png" alt="The apt command shows the number of upgradable packages at the bottom of the apt update command output"></p><p>要查看可以升级的软件包，请运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt list --upgradable</span></span></code></pre></div><p>你应该看到这样的输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~$ apt list --upgradable </span></span>
<span class="line"><span>Listing... Done</span></span>
<span class="line"><span>apparmor/jammy-updates 3.0.4-2ubuntu2.1 amd64 [upgradable from: 3.0.4-2ubuntu2]</span></span>
<span class="line"><span>brave-browser/stable 1.40.113 amd64 [upgradable from: 1.40.107]</span></span>
<span class="line"><span>evolution-data-server-common/jammy-updates,jammy-updates 3.44.2-0ubuntu1 all [upgradable from: 3.44.1-0ubuntu2]</span></span>
<span class="line"><span>evolution-data-server/jammy-updates 3.44.2-0ubuntu1 amd64 [upgradable from: 3.44.1-0ubuntu2]</span></span></code></pre></div><p><img src="https://itsfoss.com/wp-content/uploads/2022/07/apt-list-upgradable-packages-ubuntu.webp" alt="Listing all the upgradable packages"></p><p>它<strong>按字母顺序列出所有可升级的软件包</strong>以及有关当前安装版本和新可用软件包版本的信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>brave-browser/stable 1.40.113 amd64 [upgradable from: 1.40.107]</span></span></code></pre></div><p>例如，这显示我系统上安装了 Brave 浏览器，版本 1.40.107，并且版本 1.40.113 可用。</p><p>你能用这些信息做什么？让我分享一些我能想到的事情。</p><h3 id="升级所有包" tabindex="-1">升级所有包 <a class="header-anchor" href="#升级所有包" aria-label="Permalink to “升级所有包”">​</a></h3><p>这可能是大多数普通 Ubuntu 用户所做的。你可以使用以下命令升级所有可升级包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt upgrade</span></span></code></pre></div><p>它列出了将要升级的软件包，然后要求按回车或 <code>Y</code> 确认升级。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/07/upgrade-all-packages-ubuntu.webp" alt="Upgrade all packages"></p><p>如果你确定要升级所有软件包，则可以通过在命令中添加 <code>-y</code> 来跳过 “Do you want to continue” 部分。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt upgrade -y</span></span></code></pre></div><h3 id="模拟升级-但不升级任何包" tabindex="-1">模拟升级（但不升级任何包） <a class="header-anchor" href="#模拟升级-但不升级任何包" aria-label="Permalink to “模拟升级（但不升级任何包）”">​</a></h3><p>这是人们在 <code>apt list</code> 命令之前所做的。使用模拟选项，你实际上不会进行任何更改。它仅显示运行升级时将安装或升级的软件包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt -s upgrade</span></span></code></pre></div><p>你不需要使用 <code>sudo</code>（即使我在下面的截图中使用了它）。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/07/run-an-upgrade-simulation-apt-ubuntu.webp" alt="Running an upgrade simulation with apt command"></p><h3 id="仅升级选定的包" tabindex="-1">仅升级选定的包 <a class="header-anchor" href="#仅升级选定的包" aria-label="Permalink to “仅升级选定的包”">​</a></h3><p>如果你正在管理一个 Ubuntu 服务器，并且你不想升级所有软件包，而只想升级少数选定的软件包中的一个（如 MySQL/Ngnix），你可以使用 <code>apt</code> 命令轻松完成。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt --only-upgrade install package_name</span></span></code></pre></div><p>实际上，如果你在已安装且有可用更新的软件包上运行 <code>apt install</code> 命令，它将升级该软件包。</p><p>使用 <code>--only-upgrade</code> 标志，你可以确保<strong>仅升级</strong>软件包（如果已安装）。如果尚未安装，它将不会安装给定的包。</p><p>你还可以通过提供名称来升级选定的几个包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt --only-upgrade install package1 package2</span></span></code></pre></div>`,34)),t("p",null,[s[12]||(s[12]=a("你也可以做相反的事情，",-1)),i(e,{href:"https://itsfoss.com/prevent-package-update-ubuntu/"},{default:p(()=>[...s[11]||(s[11]=[a("升级时保留选定的软件包",-1)])]),_:1}),s[13]||(s[13]=a("。",-1))]),s[40]||(s[40]=n('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-mark hold package_name</span></span></code></pre></div><p>这样，当你升级所有系统包时，将不会升级给定的包。</p><p>你可以使用以下命令删除保留设置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-mark unhold package_name</span></span></code></pre></div><h3 id="是否显示内核升级" tabindex="-1">是否显示内核升级？ <a class="header-anchor" href="#是否显示内核升级" aria-label="Permalink to “是否显示内核升级？”">​</a></h3><p>这有点棘手。</p><p>当你运行 <code>apt list –upgradable</code> 命令时，它会显示所有可以升级的包。</p><p>但是如果有新的内核版本可用，它们可能不会显示，因为内核包名称以 <code>linux-headers-x-y</code> 开头。这是因为系统将它们视为新包，而不是对已安装的包 <code>linux-headers-a-b</code> 的升级。</p><p>但是，你仍然会在可升级包列表中看到 <code>linux-generic-hwe</code> 类型的包，因为该软件包将被升级（使用较新的内核）。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3>',10)),t("p",null,[s[15]||(s[15]=a("列出可升级包的能力是 ",-1)),s[16]||(s[16]=t("code",null,"apt",-1)),s[17]||(s[17]=a(" 命令为旧的 ",-1)),s[18]||(s[18]=t("code",null,"apt-get",-1)),s[19]||(s[19]=a(" 命令带来的几个新功能之一。有关此主题的更多信息，你可以阅读我 ",-1)),i(e,{href:"https://itsfoss.com/apt-vs-apt-get-difference/"},{default:p(()=>[...s[14]||(s[14]=[a("解释 apt 和 apt-get 命令之间的区别",-1)])]),_:1}),s[20]||(s[20]=a(" 的文章。",-1))]),s[41]||(s[41]=t("p",null,"作为桌面用户，我并不总是检查可以升级的软件包。我直接去升级。但是，当我管理服务器时，我更喜欢查看可用的更新，然后决定是否进行升级。",-1)),s[42]||(s[42]=t("p",null,"你呢？你觉得这个功能对你自己有用吗？",-1)),s[43]||(s[43]=t("hr",null,null,-1)),t("p",null,[s[22]||(s[22]=a("via: ",-1)),i(e,{href:"https://itsfoss.com/apt-list-upgradable/"},{default:p(()=>[...s[21]||(s[21]=[a("https://itsfoss.com/apt-list-upgradable/",-1)])]),_:1})]),t("p",null,[s[27]||(s[27]=a("作者：",-1)),i(e,{href:"https://itsfoss.com/author/abhishek/"},{default:p(()=>[...s[23]||(s[23]=[a("Abhishek Prakash",-1)])]),_:1}),s[28]||(s[28]=a(" 选题：",-1)),i(e,{href:"https://github.com/lkxed"},{default:p(()=>[...s[24]||(s[24]=[a("lkxed",-1)])]),_:1}),s[29]||(s[29]=a(" 译者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:p(()=>[...s[25]||(s[25]=[a("geekpi",-1)])]),_:1}),s[30]||(s[30]=a(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[26]||(s[26]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[33]||(s[33]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[31]||(s[31]=[a("LCTT",-1)])]),_:1}),s[34]||(s[34]=a(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:p(()=>[...s[32]||(s[32]=[a("Linux中国",-1)])]),_:1}),s[35]||(s[35]=a(" 荣誉推出",-1))])])}const x=l(r,[["render",g]]);export{C as __pageData,x as default};
